import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
} from 'typeorm';
import { ModelVersion } from '../../models/entities/model-version.entity';
import { DeploymentStatus } from '../enums/deployment-status.enum';

/**
 * Database table representation of an active running prediction server container.
 * Maps container instances to host ports and tracks current health.
 */
@Entity('deployments')
export class Deployment {
  /**
   * Unique UUID identifier generated by the database.
   */
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * The model version iteration packaged into this running container.
   */
  @ManyToOne(() => ModelVersion, (version) => version.deployments, {
    onDelete: 'CASCADE',
  })
  modelVersion: ModelVersion;

  /**
   * The local Docker container engine ID assigned to the running worker.
   */
  @Column({ type: 'varchar', nullable: true })
  containerId: string | null;

  /**
   * Remote endpoint URL utilized to ping predictions.
   */
  @Column({ type: 'varchar', nullable: true })
  url: string | null;

  /**
   * Exposed local TCP host port mapping bound to the docker container.
   */
  @Column({ type: 'integer', nullable: true })
  port: number | null;

  /**
   * Running health status of the deployment.
   */
  @Column({
    type: 'varchar',
    enum: DeploymentStatus,
    default: DeploymentStatus.STARTING,
  })
  status: DeploymentStatus;

  /**
   * Exception text captured if Docker container creation fails.
   */
  @Column({ type: 'text', nullable: true })
  errorMessage: string | null;

  /**
   * Share (0-100) of unpinned prediction traffic this deployment receives
   * when multiple RUNNING deployments exist for the same model (canary
   * traffic splitting). Irrelevant when it's the only RUNNING deployment for
   * its model — that one always gets 100% of unpinned traffic.
   */
  @Column({ name: 'traffic_weight', type: 'integer', default: 100 })
  trafficWeight: number;

  /**
   * Denormalized copy of the owning model's `organization.id`, set when the
   * deployment is created. Exists purely for Postgres row-level security
   * policies (see `shared/migrations/enable-row-level-security.sql`) to
   * scope this table by tenant without a multi-hop join through
   * modelVersion -> model -> organization. Null for personal (non-org) models.
   */
  @Column({ name: 'rls_org_id', type: 'uuid', nullable: true })
  rlsOrgId: string | null;

  /**
   * Timestamp indicating when the deployment queue job was initiated.
   */
  @CreateDateColumn()
  createdAt: Date;

  /**
   * Timestamp indicating when the container health state was last modified.
   */
  @UpdateDateColumn()
  updatedAt: Date;
}
